//! Golden parity with pi 1.4.0 `SettingsManager`.
//!
//! Fixtures: `tests/fixtures/pi/settings-cases.json` (inputs) and `settings-expected.json`,
//! generated by `scripts/pi-oracle/core-runtime/settings-resources/settings.mjs`.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    reason = "golden test asserts by unwrapping"
)]

use std::fs;
use std::path::Path;

use oino_settings::{CompactionTokenField, ResourceKind, Settings, SettingsManager, SettingsScope};
use serde_json::{Value, json};

fn fixture(name: &str) -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/pi")
        .join(name);
    serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap()
}

fn result<T: serde::Serialize, E: std::fmt::Display>(value: Result<T, E>) -> Value {
    match value {
        Ok(value) => option(Some(value)),
        Err(error) => json!({ "error": error.to_string() }),
    }
}

fn option<T: serde::Serialize>(value: Option<T>) -> Value {
    match value.map(|v| serde_json::to_value(v).unwrap()) {
        None | Some(Value::Null) => json!({ "undefined": true }),
        Some(value) => json!({ "value": value }),
    }
}

fn getters(s: &Settings) -> Value {
    let path = |p: Option<std::path::PathBuf>| p.map(|p| p.to_string_lossy().into_owned());
    let model = Some(("p", "m"));
    json!({
        "getDefaultProvider": option(s.default_provider()),
        "getDefaultModel": option(s.default_model()),
        "getDefaultThinkingLevel": option(s.default_thinking_level()),
        "getAllModelThinkingLevels": option(Some(s.model_thinking_levels())),
        "getSteeringMode": option(Some(s.steering_mode())),
        "getFollowUpMode": option(Some(s.follow_up_mode())),
        "getDefaultTools": option(s.default_tools()),
        "getEnabledModels": option(s.enabled_models()),
        "getThinkingBudgets": option(s.thinking_budgets()),
        "getSessionDir": option(path(s.session_dir())),
        "getCompactionSettings": result(s.compaction_settings(None)),
        "getCompactionSettingsForModel": result(s.compaction_settings(model)),
        "getBranchSummarySettings": option(Some(s.branch_summary_settings())),
        "getRetrySettings": option(Some(s.retry_settings())),
        "getProviderRetrySettings": option(Some(s.provider_retry_settings())),
        "getTransport": option(Some(s.transport())),
        "getHttpIdleTimeoutMs": result(s.http_idle_timeout_ms()),
        "getWebSocketConnectTimeoutMs": result(s.websocket_connect_timeout_ms()),
        "getCacheWarmingMode": option(Some(s.cache_warming_mode())),
        "getShowCacheMissNotices": option(Some(s.show_cache_miss_notices())),
        "getShellPath": option(path(s.shell_path())),
        "getShellCommandPrefix": option(s.shell_command_prefix()),
        "getImageAutoResize": option(Some(s.image_settings().auto_resize)),
        "getBlockImages": option(Some(s.image_settings().block_images)),
        "getEnableSkillCommands": option(Some(s.enable_skill_commands())),
        "getDefaultProjectTrust": option(Some(s.default_project_trust())),
        "getPackages": option(Some(s.packages())),
        "getExtensionPaths": option(Some(s.resource_paths(ResourceKind::Extensions))),
        "getSkillPaths": option(Some(s.resource_paths(ResourceKind::Skills))),
        "getPromptTemplatePaths": option(Some(s.resource_paths(ResourceKind::Prompts))),
        "getThemePaths": option(Some(s.resource_paths(ResourceKind::Themes))),
        "httpProxy": option(s.http_proxy()),
    })
}

fn arg<T: serde::de::DeserializeOwned>(op: &[Value], index: usize) -> T {
    serde_json::from_value(op[index].clone()).unwrap()
}

fn apply_op(sm: &mut SettingsManager, op: &[Value]) -> Result<(), String> {
    let name = op[0].as_str().unwrap();
    let s = |i: usize| op[i].as_str().unwrap().to_owned();
    let b = |i: usize| op[i].as_bool().unwrap();
    let strings = |i: usize| -> Vec<String> { serde_json::from_value(op[i].clone()).unwrap() };
    let outcome = match name {
        "setDefaultProvider" => sm.set_default_provider(&s(1)),
        "setCompactionEnabled" => sm.set_compaction_enabled(b(1)),
        "setDefaultModelAndProvider" => sm.set_default_model_and_provider(&s(1), &s(2)),
        "setModelThinkingLevel" => sm.set_model_thinking_level(&s(1), &s(2), arg(op, 3)),
        "removeModelThinkingLevel" => sm.remove_model_thinking_level(&s(1), &s(2)),
        "setRetryEnabled" => sm.set_retry_enabled(b(1)),
        "setImageAutoResize" => sm.set_image_auto_resize(b(1)),
        "setBlockImages" => sm.set_block_images(b(1)),
        "setProjectSkillPaths" => {
            sm.set_resource_paths(SettingsScope::Project, ResourceKind::Skills, &strings(1))
        }
        "setPackages" => sm.set_packages(
            SettingsScope::Global,
            &arg::<Vec<oino_settings::PackageSource>>(op, 1),
        ),
        "setTransport" => sm.set_transport(arg(op, 1)),
        "setCacheWarmingMode" => sm.set_cache_warming_mode(arg(op, 1)),
        "setDefaultProjectTrust" => sm.set_default_project_trust(arg(op, 1)),
        "setEnabledModels" => sm.set_enabled_models(Some(&strings(1))),
        #[allow(
            clippy::cast_possible_truncation,
            clippy::cast_sign_loss,
            reason = "pi floors the timeout"
        )]
        "setHttpIdleTimeoutMs" => {
            sm.set_http_idle_timeout_ms(op[1].as_f64().unwrap().floor() as u64)
        }
        other => panic!("unmapped op {other}"),
    };
    outcome.map_err(|e| format!("{name}: {}", e.kind))
}

/// Getters where Oino's typed enums intentionally coerce invalid values to the default instead of
/// passing them through untyped like pi.
fn typed_coercions(case: &str) -> &'static [&'static str] {
    match case {
        "merge-layers" => &["getAllModelThinkingLevels"],
        "invalid-values" => &["getSteeringMode", "getTransport", "getDefaultThinkingLevel"],
        _ => &[],
    }
}

#[test]
fn settings_manager_matches_pi() {
    let cases = fixture("settings-cases.json");
    let expected = fixture("settings-expected.json");
    let home = oino_settings::paths::home_dir().unwrap();
    for (case, want) in cases
        .as_array()
        .unwrap()
        .iter()
        .zip(expected.as_array().unwrap())
    {
        let name = case["name"].as_str().unwrap();
        let root = tempfile::Builder::new()
            .prefix("oino-settings-")
            .tempdir_in(env!("CARGO_TARGET_TMPDIR"))
            .unwrap();
        let agent = root.path().join("agent");
        let cwd = root.path().join("cwd");
        fs::create_dir_all(&agent).unwrap();
        fs::create_dir_all(cwd.join(".oino")).unwrap();
        let write = |path: &Path, value: &Value| match value {
            Value::Null => {}
            Value::String(text) => fs::write(path, text).unwrap(),
            other => fs::write(path, serde_json::to_string_pretty(other).unwrap()).unwrap(),
        };
        write(&agent.join("settings.json"), &case["global"]);
        write(&cwd.join(".oino/settings.json"), &case["project"]);
        let trusted = case["trusted"].as_bool().unwrap_or(true);
        let mut sm = SettingsManager::create(&cwd, &agent, trusted);
        let mut op_errors = Vec::new();
        for op in case["ops"].as_array().into_iter().flatten() {
            if let Err(error) = apply_op(&mut sm, op.as_array().unwrap()) {
                op_errors.push(error);
            }
        }
        let s = sm.settings();
        assert_eq!(
            serde_json::to_string(s.merged()).unwrap(),
            serde_json::to_string(&want["settings"]).unwrap(),
            "{name}: merged settings"
        );
        assert_eq!(
            Value::Object(s.global().clone()),
            want["global"],
            "{name}: global"
        );
        assert_eq!(
            Value::Object(s.project().clone()),
            want["project"],
            "{name}: project"
        );

        let got = serde_json::to_string(&getters(s))
            .unwrap()
            .replace(home.to_str().unwrap(), "$HOME");
        let got: Value = serde_json::from_str(&got).unwrap();
        for (getter, want_value) in want["getters"].as_object().unwrap() {
            if typed_coercions(name).contains(&getter.as_str()) {
                continue;
            }
            assert_eq!(&got[getter], want_value, "{name}: {getter}");
        }

        let read = |path: &Path| {
            fs::read_to_string(path)
                .ok()
                .map_or(Value::Null, Value::from)
        };
        assert_eq!(
            read(&agent.join("settings.json")),
            want["files"]["global"],
            "{name}: global file"
        );
        assert_eq!(
            read(&cwd.join(".oino/settings.json")),
            want["files"]["project"],
            "{name}: project file"
        );
        assert_eq!(
            Value::from(op_errors),
            want["opErrors"],
            "{name}: op errors"
        );
        let scopes: Vec<Value> = sm
            .drain_errors()
            .iter()
            .map(|e| serde_json::to_value(e.scope).unwrap())
            .collect();
        assert_eq!(Value::from(scopes), want["errors"], "{name}: load errors");
    }
}

#[test]
fn compaction_token_field_resolution() {
    let mut initial = serde_json::Map::new();
    initial.insert(
        "compaction".into(),
        json!({"reserveTokens": 10, "modelOverrides": {"a/b": {"reserveTokens": 3}}}),
    );
    let sm = SettingsManager::in_memory(initial);
    let s = sm.settings();
    assert_eq!(
        s.compaction_token(CompactionTokenField::ReserveTokens, Some(("a", "b"))),
        Ok(3)
    );
    assert_eq!(
        s.compaction_token(CompactionTokenField::ReserveTokens, Some(("x", "y"))),
        Ok(10)
    );
    assert_eq!(
        s.compaction_token(CompactionTokenField::KeepRecentTokens, None),
        Ok(20_000)
    );
}
